frappe.ui.form.on('Employee', {
    onload: function(frm) {
        frm.set_value('salaire_old', frm.doc.salaire_de_base);
        frm.set_value('employee_category_old', frm.doc.employee_category_details);
    },
    
    before_save: function(frm) {
        
        var salaireBase = frm.doc.salaire_de_base / 26;
        var salaireMoyen = salaireBase;
        var categorie_true;
        
        
      
        if (salaireMoyen <= 5) {
            categorie_true = "MAO1-1.I";
        } else if (salaireMoyen > 5 && salaireMoyen <= 5.8) {
            categorie_true = "MAL1-2.I";
        } else if (salaireMoyen > 5.8 && salaireMoyen <= 6.65) {
            categorie_true = "TSP0-3.II";
        } else if (salaireMoyen > 6.65 && salaireMoyen <= 7.7) {
            categorie_true = "TSQ1-4.III";
        } else if (salaireMoyen > 7.7 && salaireMoyen <= 8.9) {
            categorie_true = "TSQ2-5.III";
        } else if (salaireMoyen > 8.9 && salaireMoyen <= 10.3) {
            categorie_true = "TSQ3-6.III";
        } else if (salaireMoyen > 10.3 && salaireMoyen <= 11.85) {
            categorie_true = "TRQ1-7.IV";
        } else if (salaireMoyen > 11.85 && salaireMoyen <= 13.7) {
            categorie_true = "TRQ2-8.IV";
        } else if (salaireMoyen > 13.7 && salaireMoyen <= 15.85) {
            categorie_true = "THQ0-9.V";
        } else if (salaireMoyen > 15.85 && salaireMoyen <= 18.30) {
            categorie_true = "MAT1-10.M";
        } else if (salaireMoyen > 18.3 && salaireMoyen <= 21.10) {
            categorie_true = "MAT2-11.M";
        } else if (salaireMoyen > 21.1 && salaireMoyen <= 24.4) {
            categorie_true = "MAT3-12.M";
        } else if (salaireMoyen > 24.4 && salaireMoyen <= 28.2) {
            categorie_true = "MAT4-13.M";
        } else if (salaireMoyen > 28.2 && salaireMoyen <= 32.55) {
            categorie_true = "CAC1-14.CC";
        } else if (salaireMoyen > 32.55 && salaireMoyen <= 37.6) {
            categorie_true = "CAC2-15.CC";
        } else if (salaireMoyen > 37.6 && salaireMoyen <= 43.4) {
            categorie_true = "CAC3-16.CC";
        } else if (salaireMoyen > 43.4 && salaireMoyen <= 50) {
            categorie_true = "CAC4-17.CC";
        } else {
            categorie_true = "CAD";
        }
        
        
        
        var categorie = categorie_true;
        var salaire = frm.doc.salaire_de_base;
        var date_ajuste = get_today();
        
        
 
        var date_joining = new Date(frm.doc.date_of_joining); // Assurer que c'est un objet Date
        
        var year = date_joining.getFullYear();
        var month = date_joining.getMonth() + 1; // Ajouter 1 car getMonth() renvoie 0 pour janvier
        var day = date_joining.getDate();
        
        var date_pay = year + '-' + ('0' + month).slice(-2) + '-' + day;
        
        // Ajustement de la date de paie en fonction du jour et du type d'emploi
        if (frm.doc.employment_type === 'Nationaux') {
            if (day >= 21 && day <= 31) {
                // Même mois, jour ajusté à 21
                date_pay = year + '-' + ('0' + month).slice(-2) + '-' + '21';
            } else if (day >= 1 && day <= 20) {
                // Mois de date d'embauche, jour ajusté à 21
                date_pay = year + '-' + ('0' + month).slice(-2) + '-' + '21';
            }
        }else if (frm.doc.employment_type === 'Expatriés') {
            // Pour les Expatriés, ajuster la date au premier jour du même mois
            date_pay = year + '-' + ('0' + month).slice(-2) + '-' + '01';
        }
                
        
        var child_table = "Mois Conge Actuel";
        //frappe.msgprint("La tableau des salaires est vide. Veuillez ajouter des salaires.  " + !frm.doc.salaire_de_base);
        
        if (!frm.doc.salaire_old) {
            //frappe.msgprint('status ok fff 0' + frm.doc.status + " tableau " + frm.doc.salaire_de_base);
            if (frm.doc.salaire_de_base > 0) {
                
                frm.doc.salaire_old = frm.doc.salaire_de_base
                frm.add_child('salaire_employee', {'date_ajuste':date_ajuste, 'categorie': categorie, 'salaire': salaire, 'date_debut':date_pay});
                frm.refresh_field('salaire_employee');
                frm.refresh();
            }
            //frappe.msgprint("Le tableau des salaires est vide. Veuillez ajouter des salaires.");
        }
        else
        {
            var child_row = frm.doc.salaire_employee[frm.doc.salaire_employee.length - 1];
            
            
            if (child_row) {
                //frappe.msgprint('status ok fff 1eer ' + frm.doc.salaire_de_base +"  -  " + frm.doc.salaire_old);
                if (frm.doc.salaire_de_base != frm.doc.salaire_old) {
                     //frappe.msgprint(`Ceci est un message. ${frm.doc.salaire_de_base}`);
                     
                    var date_joining = new Date(date_ajuste); // Assurer que c'est un objet Date
    
                    var year = date_joining.getFullYear();
                    var month = date_joining.getMonth() + 1; // Ajouter 1 car getMonth() renvoie 0 pour janvier
                    var day = date_joining.getDate();
                    
                    var date_pay = year + '-' + ('0' + month).slice(-2) + '-' + day;
                    
                    // Ajustement de la date de paie en fonction du jour et du type d'emploi
                    if (frm.doc.employment_type === 'Nationaux') {
                        if (day >= 21 && day <= 31) {
                            // Même mois, jour ajusté à 21
                            date_pay = year + '-' + ('0' + month).slice(-2) + '-' + '21';
                        } else if (day >= 1 && day <= 20) {
                            // Mois de date d'embauche, jour ajusté à 21
                            date_pay = year + '-' + ('0' + month).slice(-2) + '-' + '21';
                        }
                    }else if (frm.doc.employment_type === 'Expatriés') {
                        // Pour les Expatriés, ajuster la date au premier jour du même mois
                        date_pay = year + '-' + ('0' + month).slice(-2) + '-' + '01';
                    }
                        
                    var today = new Date();
                    
                    today.setDate(today.getDate() - 1);
                    
                    var year = today.getFullYear();
                    var month = ('0' + (today.getMonth() + 1)).slice(-2); // Months are zero-based
                    var day = ('0' + today.getDate()).slice(-2);
                    
                    if (month > 12){
                        month = 1
                        year = year + 1
                    }
                    frm.doc.salaire_employee[cur_frm.doc.salaire_employee.length -1].date_fin = year + '-' + month + '-' + day;
                     
                    frm.doc.salaire_old = frm.doc.salaire_de_base
                    frm.add_child('salaire_employee', {'date_ajuste':date_ajuste, 'categorie': categorie, 'salaire': salaire,'date_debut':date_pay});
                    frm.refresh_field('salaire_employee');
                    frm.refresh();
                }
    
            } else {
                //frappe.msgprint(`Ceci est un message. ${frm.doc.salaire_de_base}`);
                frm.add_child('salaire_employee', {'date_ajuste':date_ajuste, 'categorie': categorie, 'salaire': salaire,'date_debut':date_pay});
                frm.refresh_field('salaire_employee');
                frm.refresh();
            }
        }
    }
});

frappe.ui.form.on('Loan Type', {
	onload: function(frm) {
		$.each(["penalty_income_account", "interest_income_account"], function (i, field) {
			frm.set_query(field, function () {
				return {
					"filters": {
						"company": frm.doc.company,
						"root_type": "Income",
						"is_group": 0
					}
				};
			});
		});

		$.each(["payment_account", "loan_account", "disbursement_account"], function (i, field) {
			frm.set_query(field, function () {
				return {
					"filters": [
                        ["company", "=", frm.doc.company],
                        ["root_type", "IN", ["Asset", "Liability"]],
                        ["is_group", "=", 0]
                    ]
				};
			});
		});
	}
});

frappe.ui.form.on('Employee', {
	employee_category_details(frm) {
		// your code here
		frappe.db.get_doc("Employee Category Details", frm.doc.employee_category_details).then(r => {
		    //alert(r.conge_days);
		    frm.doc.conge_days = r.conge_days;
		    //frm.doc.conge_days_5_years = r.conge_days_5_years;
    		frm.doc.basic_salary_per_day = r.basic_salary_per_day;
    		frm.doc.basic_salary_per_hour = r.basic_salary_per_hour;
    		frm.doc.logement = r.logement;
    		frm.doc.transport = r.transport;
    		frm.doc.conge_days_final_settlement = r.conge_days_final_settlement;
    		frm.doc.conge_year_final_settlement = r.conge_year_final_settlement;
    		frm.dirty();
		    frm.refresh();
		});
	}

});

